const API_TOKEN = '1985d3b7ffcc266add8f005be68caf8ff8ec605f';
const BASE = 'https://api.pipedrive.com/v1';
const body = $input.first().json.body || $input.first().json;
const entity = body.entity || 'deals';
const dateFrom = body.dateFrom;
const dateTo = body.dateTo;

async function apiCall(method, path, payload) {
  const opts = {method, url: BASE + path + (path.includes('?') ? '&' : '?') + 'api_token=' + API_TOKEN};
  if (payload) {opts.body = payload; opts.headers = {'Content-Type':'application/json'};}
  return await this.helpers.httpRequest(opts);
}

let items = [];

if (entity === 'deals') {
  let conditions = [];
  if (dateFrom) conditions.push({field_id:12465,operator:'>=',value:dateFrom});
  if (dateTo) conditions.push({field_id:12465,operator:'<=',value:dateTo});
  let filterId = null;
  try {
    if (conditions.length) {
      const fp = {name:'sync_'+Date.now(),type:'deals',conditions:{glue:'and',conditions:[{glue:'and',conditions:conditions.map(c=>({object:'deal',field_id:c.field_id,operator:c.operator,value:c.value,extra_value:null}))}]}};
      const fRes = await apiCall.call(this,'POST','/filters',fp);
      filterId = fRes.data.id;
    }
    let start=0, hasMore=true, pages=0;
    while(hasMore && pages<50){
      let url='/deals?limit=500&start='+start;
      if(filterId) url+='&filter_id='+filterId;
      const r = await apiCall.call(this,'GET',url);
      if(r.data) {
        for(const d of r.data) {
          items.push({json:{
            id: d.id,
            title: d.title || '',
            status: d.status || 'open',
            pipeline_id: d.pipeline_id || null,
            stage_id: d.stage_id || null,
            owner_id: typeof d.user_id==='object' ? d.user_id.id : (d.user_id || null),
            owner_name: typeof d.user_id==='object' ? (d.user_id.name||'') : '',
            person_name: typeof d.person_id==='object' ? (d.person_id.name||'') : '',
            org_name: typeof d.org_id==='object' ? (d.org_id.name||'') : '',
            value: d.value || 0,
            currency: d.currency || 'UAH',
            label: String(d.label || ''),
            add_time: d.add_time || null,
            update_time: d.update_time || null,
            won_time: d.won_time || null,
            lost_time: d.lost_time || null,
            lost_reason: d.lost_reason || '',
            raw_data: JSON.stringify(d)
          }});
        }
      }
      const p = r.additional_data && r.additional_data.pagination;
      hasMore = p && p.more_items_in_collection;
      if(hasMore) start = p.next_start;
      pages++;
    }
  } finally {
    if(filterId) try{await apiCall.call(this,'DELETE','/filters/'+filterId);}catch(e){}
  }
}

if (!items.length) items.push({json:{_empty:true,entity,count:0}});
return items;

const items = $input.all();
const count = items.filter(i => !i.json._empty).length;
return [{json:{success:true, entity:'deals', count}}];
